## Testing

Tests first, as everywhere in this repo, and none may contain Berkeley
bytes.

- Python (`tools/tests`):
  - the PICT decoder and resource-fork parser, against small PICTs and
    resource forks the test builds itself;
  - sector-tag stripping on a synthetic image;
  - one optional test that runs the tool on the real image when it is
    present and checks five colour and five mono 64×64 sprites come out.
    Skipped, not failed, without it.
- C (native, Unity, with stand-in sprites such as solid colours):
  - flap order 0 1 2 3 2 1 0;
  - per-step motion for speeds 1-3;
  - the collision nudge, both branches, and the keep-base-step fallback;
  - removal once off screen and respawn at the top or right edge;
  - initial placement fully inside the bounds;
  - at most 4 placement tries, with the slot left empty and retried;
  - the doneness subtraction, including clamping at 0;
  - the 1-bit expansion to white on black;
  - **trail wiping**: after several steps, every non-black pixel lies inside
    some flyer's current rect.
- Mutation-check the new tests, as `AGENTS.md` asks.
- When the image is present, the suite's every-hack run (3000 frames under
  ASan, leak check across restarts) covers `ad-flyingtoasters` too.
- Under `#ifdef HAVE_AFTER_DARK_TOASTERS`, add the hack to
  `test_hacks.c`'s expected names and its baselines.
- On the device: flash a build pinned with `START_HACK="ad-flyingtoasters"`
  and rotation off (ask Rod first), capture `fps=` and `rows=` over a few
  minutes, and report the mean and the worst window. Restarts make random
  picks, but to show Rod each combination on purpose, flash with the force
  flags: colour Light, Medium and Dark, then 1-bit. Only Rod can confirm the
  look; tell him what to check: the colour toast's shade in the logged
  doneness, and white line art in 1-bit mode.

## Licensing and housekeeping
ad_sim.c
ad_sim.h
ad_sprites.c
ad_sprites.h
#ifndef AD_SIM_H
#define AD_SIM_H

#define AD_MAX_FLYERS 20
#define AD_RECT 70 /* flyer rect: 64 art + 6 px strip */
#define AD_STRIP 6

/* QuickDraw order; right and bottom are exclusive. */
typedef struct {
  int top, left, bottom, right;
} AdRect;

typedef struct {
  int live, toast, speed, frame, flap_down;
  AdRect r;
} AdFlyer;

typedef struct {
  AdRect bounds;
  int n, running;
  AdFlyer f[AD_MAX_FLYERS];
  long (*rnd)(void); /* random() in the hack; scripted in tests */
} AdSim;

/* sprite: 0-3 toaster frame, 4 toast. Called after the flyer's move. */
typedef void (*AdDrawFn)(void *ctx, const AdRect *r, int sprite);

/* Scatter n flyers inside bounds. Does not draw. */
void ad_sim_init(AdSim *, AdRect bounds, int n, long (*rnd)(void));
/* Draw each live flyer once, in slot order (advances toaster frames). */
void ad_sim_draw_all(AdSim *, AdDrawFn, void *ctx);
/* One simulation step: move, respawn, collide, draw. */
void ad_sim_step(AdSim *, AdDrawFn, void *ctx);
/* First live flyer (other than slot i) overlapping cand: sets the nudge. */
int ad_sim_collision(const AdSim *, int i, AdRect cand, int *dv, int *dh);

#endif
#ifndef AD_SPRITES_H
#define AD_SPRITES_H

#include <stdint.h>

typedef enum { AD_DONE_LIGHT, AD_DONE_MEDIUM, AD_DONE_DARK } AdDoneness;
typedef struct {
  int colour;
  AdDoneness doneness;
} AdChoice;

AdChoice ad_choose(uint32_t r); /* bit 0: colour; (r >> 1) % 3: doneness */
void ad_apply_doneness(unsigned char *rgb, int pixels, AdDoneness d);
/* 512 bytes of 64x64 bits, MSB first; a set bit is black, a clear bit white. */
void ad_expand_mono(const unsigned char bits[512], unsigned char rgb[64 * 64 * 3]);
/* 70x70 RGB565 (what a 16-bit XImage holds): art at x 0..63, y 6..69; rows
 * 0..5 and columns 64..69 are black. */
void ad_build_sprite(const unsigned char rgb[64 * 64 * 3], uint16_t out[70 * 70]);

#endif
#ifndef RUNNER_HACK_ENTRY_H
#define RUNNER_HACK_ENTRY_H

#include "x11shim/xshim.h"

#ifdef __cplusplus
extern "C" {
#endif

struct xscreensaver_function_table;

/* Mirrors the callbacks in xscreensaver's xscreensaver_function_table. For a
 * hack built on xlockmore.h the callbacks above are unused: `xsft` points at
 * the hack's own table, which the runner completes with its setup_cb. */
typedef struct HackEntry {
  const char *name;
  const char *const *defaults;
  void *(*init)(Display *, Window);
  unsigned long (*draw)(Display *, Window, void *closure); /* delay in us */
  void (*free)(Display *, Window, void *closure);
  struct xscreensaver_function_table *xsft;
  /* Device-specific resources that beat the hack's own defaults. */
  const char *const *overrides;
  /* Nonzero to start each push at a fixed point in the panel's refresh, so the
   * seam between the old and new picture lands where it does no harm (see
   * main.cpp). It costs up to one refresh of latency a frame, so a hack asks
   * only if thin lines moving a few pixels a frame show the seam. The wait
   * happens in present(); an overlay redraw made later, while the loop waits
   * out the hack's delay, is not counted against that delay, so a synced hack
   * with a long delay could overrun it. Unknown Pleasures never does. */
  int sync_to_refresh;
} HackEntry;

#ifdef __cplusplus
}
#endif

#endif

